/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  const nums = line.split(",").map(Number);

  console.log(getResult(nums));
});

function getResult(nums) {
  // 矩阵 n x n
  const n = Math.sqrt(nums.length);

  // 未污染区域数量
  let total = nums.length;

  // 矩阵
  const matrix = new Array(n).fill(0).map(() => new Array(n));

  // BFS队列
  let queue = [];

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      matrix[i][j] = nums[i * n + j];

      if (matrix[i][j] === 1) {
        queue.push([i, j]);
        total--;
      }
    }
  }

  if (queue.length === 0 || queue.length === nums.length) {
    return -1;
  }

  // 上下左右方位偏移量
  const offsets = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  // 扩散天数
  let day = 0;

  while (queue.length > 0 && total > 0) {
    const newQueue = [];

    for (const [i, j] of queue) {
      for (const [offsetI, offsetJ] of offsets) {
        const newI = i + offsetI;
        const newJ = j + offsetJ;

        if (
          newI >= 0 &&
          newI < n &&
          newJ >= 0 &&
          newJ < n &&
          matrix[newI][newJ] == 0
        ) {
          matrix[newI][newJ] = 1;
          newQueue.push([newI, newJ]);
          total--;
        }
      }
    }

    queue = newQueue;
    day++;
  }

  return day;
}

