#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_SIZE 1024

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();
void addLast_LinkedList(LinkedList *link, int ele);

int matrix[MAX_SIZE][MAX_SIZE] = {0};
int nums[MAX_SIZE * MAX_SIZE];
int nums_size = 0;

int getResult();

int main() {
    while(scanf("%d", &nums[nums_size++])) {
        if(getchar() != ',') break;
    }

    printf("%d\n", getResult());

    return 0;
}

int getResult() {
    // 矩阵 n x n
    int n = (int) sqrt(nums_size);

    // 未污染水域数量
    int total = nums_size;

    // BFS队列
    LinkedList* queue = new_LinkedList();

    for(int i=0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            matrix[i][j] = nums[i * n + j];

            if(matrix[i][j] == 1) {
                addLast_LinkedList(queue, i * n + j);
                total--;
            }
        }
    }

    if(queue->size == 0 || queue->size == nums_size) {
        return -1;
    }

    // 上下左右偏移量
    int offsets[4][2] = {{1,  0},
                         {-1, 0},
                         {0,  1},
                         {0,  -1}};

    // 扩散时间
    int day = 0;

    // 如果扩散点没有了，或者所有点已被扩散，则停止循环
    while (queue->size > 0 && total > 0) {
        LinkedList *newQueue = new_LinkedList();

        ListNode *cur = queue->head;
        while (cur != NULL) {
            int x = cur->ele / n;
            int y = cur->ele % n;

            for (int i = 0; i < 4; i++) {
                int newX = x + offsets[i][0];
                int newY = y + offsets[i][1];

                if (newX >= 0 && newX < n && newY >= 0 && newY < n && matrix[newX][newY] == 0) {
                    // 将点被扩散的时间记录为该点的值
                    matrix[newX][newY] = 1;
                    // 被扩散到的点将变为新的扩散源
                    addLast_LinkedList(newQueue, newX * n + newY);
                    // 未被扩散点的数量--
                    total--;
                }
            }
            cur = cur->next;
        }

        queue = newQueue;
        day++;
    }

    return day;
}

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}
